// Generated by vibelang from bench/startup.ts; the migrate flow writes it again with each batch.
// Standalone ChatApi startup benchmark. Keep timing budgets out of the parallel unit gate.
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdir, mkdtemp, rm, writeFile } from "node:fs/promises";
import { cpus, loadavg, tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { parseArgs } from "node:util";
import { bundle } from "../worker/test/startup/bundle.js";
const { values } = parseArgs({ options: { out: { type: "string" } } });
assert(values.out, "--out must name a fresh artifact directory");
const out = resolve(values.out);
// Refuse existing results, including failures, so a stale receipt cannot appear successful.
await mkdir(out);
const temporary = await mkdtemp(join(tmpdir(), "chatapi-startup-bench-"));
const budgetMs = 200;
const before = loadavg();
try {
    const output = await bundle();
    const hashes = {};
    for (const file of output) {
        const contents = file.type === "chunk" ? file.code : file.source;
        const path = join(temporary, file.fileName);
        await mkdir(dirname(path), { recursive: true });
        await writeFile(path, contents);
        hashes[file.fileName] = createHash("sha256").update(contents).digest("hex");
    }
    const samples = [0, 1, 2].map(() => {
        const ran = spawnSync(process.execPath, ["--no-warnings",
            fileURLToPath(new URL("../worker/test/startup/evaluate.mjs", import.meta.url)), join(temporary, "ChatApi.js")], { encoding: "utf8" });
        assert.equal(ran.status, 0, ran.stderr);
        const sample = JSON.parse(ran.stdout.trim().split("\n").at(-1));
        assert(Number.isFinite(sample.evaluationMs) && sample.evaluationMs > 0);
        assert(Number.isFinite(sample.cpuMs) && sample.cpuMs > 0);
        return sample;
    });
    const medianMs = samples.map(sample => sample.evaluationMs).sort((a, b) => a - b)[1];
    const revision = spawnSync("jj", ["--ignore-working-copy", "log", "-r", "@", "--no-graph", "-T", "commit_id"], {
        cwd: fileURLToPath(new URL("..", import.meta.url)), encoding: "utf8",
    });
    assert.equal(revision.status, 0, revision.stderr);
    const result = {
        ok: medianMs < budgetMs, budgetMs, medianMs, samples, hashes,
        method: "Three fresh Node processes importing the real Alchemy bundle; median elapsed module import, no warmup. OS file cache is retained. Cloudflare imports use the startup-only Node adapter.",
        limitations: "Node elapsed time is sensitive to host contention and is not Cloudflare startup CPU. No live deployment was measured by this command.",
        environment: { date: new Date().toISOString(), revision: revision.stdout.trim(), node: process.version,
            platform: process.platform, arch: process.arch, cpu: cpus()[0]?.model, cores: cpus().length,
            loadBefore: before, loadAfter: loadavg() },
    };
    await writeFile(join(out, "result.json"), `${JSON.stringify(result, null, 2)}\n`);
    console.log(`ChatApi startup: ${medianMs.toFixed(1)} ms median / ${budgetMs} ms budget; ${join(out, "result.json")}`);
    assert(result.ok, `ChatApi startup median ${medianMs} ms exceeds ${budgetMs} ms`);
}
catch (error) {
    await writeFile(join(out, "failure.json"), `${JSON.stringify({ message: String(error) }, null, 2)}\n`);
    throw error;
}
finally {
    await rm(temporary, { recursive: true, force: true });
}
